module patience_merge(input wire clk, input wire rst_n, input wire start, input wire [2:0] N_in, input wire [2:0] L_seq [0:7], input wire [7:0] seq_data [0:7][0:7], output reg [7:0] result_value, output reg result_valid, output reg done); reg [2:0] ptr [0:7]; reg [2:0] state; reg [2:0] scan_idx; reg [2:0] best_idx; reg [2:0] k; wire all_done; localparam IDLE = 3'd0, FIND_BEST = 3'd1, SCAN = 3'd2, COMPARE = 3'd3, OUTPUT = 3'd4, CHECK_DONE = 3'd5; always @ (ptr, L_seq, N_in) begin all_done = 1'b1; if (N_in >=1) all_done &= (ptr[0] >= L_seq[0]); if (N_in >=2) all_done &= (ptr[1] >= L_seq[1]); if (N_in >=3) all_done &= (ptr[2] >= L_seq[2]); if (N_in >=4) all_done &= (ptr[3] >= L_seq[3]); if (N_in >=5) all_done &= (ptr[4] >= L_seq[4]); if (N_in >=6) all_done &= (ptr[5] >= L_seq[5]); if (N_in >=7) all_done &= (ptr[6] >= L_seq[6]); if (N_in >=8) all_done &= (ptr[7] >= L_seq[7]); end always @(posedge clk) begin if (!rst_n) begin ptr <= 0; state <= IDLE; scan_idx <= 0; best_idx <= 3'd3; k <= 0; end else begin case (state) IDLE: if (start) begin state <= FIND_BEST; end else begin state <= IDLE; end FIND_BEST: state <= SCAN; scan_idx <= 0; best_idx <= 3'd3; SCAN: begin if (scan_idx >= N_in) begin if (best_idx < N_in) begin state <= OUTPUT; end else begin state <= CHECK_DONE; end end else begin if (ptr[scan_idx] >= L_seq[scan_idx]) begin scan_idx <= scan_idx + 1; state <= SCAN; end else begin if (best_idx == 3'd3) begin best_idx <= scan_idx; scan_idx <= scan_idx + 1; state <= SCAN; end else begin state <= COMPARE; k <= 0; end end end end COMPARE: begin reg [7:0] val_scan, val_best; reg val_scan_valid, val_best_valid; val_scan_valid = (ptr[scan_idx] + k) < L_seq[scan_idx]; val_best_valid = (ptr[best_idx] + k) < L_seq[best_idx]; if (val_scan_valid && val_best_valid) begin val_scan = seq_data[scan_idx][ptr[scan_idx] + k]; val_best = seq_data[best_idx][ptr[best_idx] + k]; if (val_scan < val_best) begin best_idx <= scan_idx; scan_idx <= scan_idx + 1; state <= SCAN; end else if (val_scan > val_best) begin scan_idx <= scan_idx + 1; state <= SCAN; end else begin if (k < 7) begin k <= k + 1; state <= COMPARE; end else begin scan_idx <= scan_idx + 1; state <= SCAN; end end end else begin if (!val_scan_valid && !val_best_valid) begin scan_idx <= scan_idx + 1; state <= SCAN; end else if (!val_scan_valid) begin best_idx <= scan_idx; scan_idx <= scan_idx + 1; state <= SCAN; end else begin scan_idx <= scan_idx + 1; state <= SCAN; end end end OUTPUT: begin result_value <= seq_data[best_idx][ptr[best_idx]]; ptr[best_idx] <= ptr[best_idx] + 1; result_valid <= 1'b1; state <= CHECK_DONE; end CHECK_DONE: begin result_valid <= 1'b0; if (all_done) begin done <= 1'b1; state <= IDLE; end else begin state <= FIND_BEST; end end endcase end end endmodule